// applyEmphasis converts the first __...__ pair to <strong> and the first
// _..._ pair to <em>, matching the original implementation's behavior.
func applyEmphasis(markdown string) string {
	markdown = replacePair(markdown, "__", "<strong>", "</strong>")
	return replacePair(markdown, "_", "<em>", "</em>")
}

// replacePair wraps the first pair of marker occurrences in open/close tags.
func replacePair(s, marker, open, close string) string {
	i := strings.Index(s, marker)
	if i < 0 {
		return s
	}
	j := strings.Index(s[i+len(marker):], marker)
	if j < 0 {
		return s
	}
	j += i + len(marker)
	return s[:i] + open + s[i+len(marker):j] + close + s[j+len(marker):]
}
```

